export const ORDER_SPEC = `# Order Workflow Specification

## Purpose

Covers the fulfilment half of the checkout flow: every order moves from
\`placed\` to either \`paid\` or \`cancelled\`, and only a paid order can complete.

## Contracts

| Function | Returns | Visibility |
| --- | --- | --- |
| \`cancel(orderId: string, reason: string)\` | OrderState | exported |
| \`complete(orderId: string)\` | OrderState | exported |
| \`addLine(orderId: string, line: OrderLine)\` | OrderState | exported |

## Behavioural rules / Guard conditions

| Function | When | Then |
| --- | --- | --- |
| cancel | \`!orderId\` | throw |
| cancel | \`!reason\` | throw |
| complete | \`order.status !== 'paid'\` | throw |
| addLine | \`line.quantity <= 0\` | throw |

## Error paths

| Function | Error | Message |
| --- | --- | --- |
| cancel | Error | orderId and reason are required |
| complete | Error | only a paid order can complete |
| addLine | Error | line quantity must be positive |

## Data types

### interface \`OrderLine\`

- \`sku: string\`
- \`quantity: number\`
- \`unitPrice: number\`

### interface \`OrderState\`

- \`orderId: string\`
- \`status: string\`
- \`lines: OrderLine[]\`
- \`total: number\`
`;

export const CACHE_SPEC = `# Cache Store Service

## Overview

A small, dependency-free cache with TTL handling. The declarations below are the
contract that the service must satisfy.

## Contracts

\`\`\`typescript
export interface CacheEntry {
  key: string;
  value: string;
  expiresAt: number;
}

export interface CacheStats {
  hits: number;
  misses: number;
  size: number;
}

export class CacheStore {
  get(key: string): Promise<CacheEntry | undefined> { ... }
  set(key: string, value: string, ttlSeconds?: number): Promise<void> { ... }
  prune(): CacheStats { ... }
}
\`\`\`

## Guard conditions

| Function | When | Then |
| --- | --- | --- |
| CacheStore.get | \`!key\` | throw |
| CacheStore.set | \`ttlSeconds < 0\` | throw |
| CacheStore.set | \`!value\` | throw |

## Error paths

| Function | Error | Message |
| --- | --- | --- |
| CacheStore.get | Error | key is required |
| CacheStore.set | Error | ttlSeconds must not be negative |

## Data types

### interface \`PruneResult\`

- \`removed: number\`
- \`remaining: number\`
`;

